function renderPDicts(body,tab,fresh){renderPDicts0(body,tab,fresh);const t=pdTabs().find(x=>x.id===tab);if(t)body.insertAdjacentHTML('afterbegin',dgHead(PD_TAB_DG[tab]||t.label))}
